"""Dependency-free static site builder. Public assets only go into dist/."""
from pathlib import Path
import json, html, shutil
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
OUT.mkdir(exist_ok=True)
def esc(s): return html.escape(str(s),quote=True)
DATA=json.loads((ROOT/'data.json').read_text())
FORM='https://docs.google.com/forms/d/e/1FAIpQLScwfTCX9x7BFOxoQiwXxrrMNqTpDuUcYrFIb93hOtGn78XOYw/viewform'
SUGGEST='https://docs.google.com/forms/d/e/1FAIpQLSdCTlbrDc3I1dgKsh0318ZYgo0CrjSVevpBZJhyBJZzJYbpGw/viewform'
LABELS={'public':'Public dining','events':'Private / group events','members':'Members only','discretion':'Ask management first','clarify':'Policy needs clarification'}

def shell(title,description,body,active='Restaurants',prefix='',path='index.html'):
    nav=''.join(f'<a href="{prefix}{url}" '+('aria-current="page" ' if name==active else '')+f'>{name}</a>' for name,url in [('Restaurants','index.html'),('Journal','journal.html'),('The club','club.html'),('About','about.html')])
    return f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | London Corkage Club</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#773344"><meta property="og:title" content="{esc(title)} | London Corkage Club"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><link rel="icon" href="{prefix}images/wine-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Lato:wght@400;700&family=Playfair+Display:ital,wght@0,400;0,500;0,600;1,400;1,500&display=swap" rel="stylesheet"><link rel="stylesheet" href="{prefix}styles.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="masthead wrap"><a class="brand" href="{prefix}index.html"><img src="{prefix}images/wine-icon.png" width="29" height="29" alt=""><span>London Corkage Club<span class="brand-note">Good food. Your wine.</span></span></a><nav aria-label="Main navigation">{nav}</nav><a class="button small" href="{prefix}club.html#join">Join the waitlist <span aria-hidden="true">↗</span></a></div></header>{body}<footer class="site-footer wrap"><div><a class="footer-brand" href="{prefix}index.html">London Corkage Club</a><p>A good bottle deserves a good table.</p></div><div><a href="{prefix}about.html#how-we-check">How we check policies</a><a href="{prefix}journal.html">Notes from the journal</a><a href="{SUGGEST}" target="_blank" rel="noopener noreferrer">Suggest a restaurant ↗</a></div><p class="fineprint">An independent London guide. No restaurant or merchant affiliation is implied. Always agree corkage with the restaurant before your visit.</p></footer></body></html>'''

POSTS=[
{'slug':'a-better-bottle-a-better-evening','category':'The corkage guide','title':'A better bottle. A better evening.','deck':'Corkage is not just a way around a wine list. It is a reason to finally open the bottle you have been saving.','art':'bottle','read':'4 minute read','body':'''<p class="lead">There is a bottle in the cupboard with no date attached to it. Too good for a Tuesday, apparently. Waiting for an occasion that never quite arrives. A restaurant that welcomes corkage gives it somewhere to go.</p><p>Corkage is the fee a restaurant charges when you bring your own wine. It pays for part of the experience around the bottle: glassware, opening, service and the table at which you drink it. It is not a universal entitlement, and a restaurant with a good wine list has perfectly sound reasons for setting conditions.</p><h2>Start with the table, not the saving</h2><p>Choose somewhere you actually want to eat. Then work out whether your bottle suits the food and whether the fee makes sense. Bringing an inexpensive everyday wine to a restaurant with a substantial corkage charge rarely improves the evening. Bringing a mature bottle you have looked after for years is a different proposition.</p><p>You need not be a collector. Perhaps it is a wine from a holiday, a gift, or a bottle a local merchant suggested for dinner. The point is to drink something you are looking forward to, with food that gives it a fair chance.</p><h2>Ask one useful question</h2><p>When booking, give the restaurant the wine’s name, vintage and bottle size, and say how many bottles you plan to bring. Ask for the total corkage charge, including any service charge. A magnum is not necessarily charged as two standard bottles, and sparkling wine may have a separate rate.</p><blockquote>“We would like to bring one 750ml bottle for two of us. Is that possible for this booking, and what would the total corkage charge be?”</blockquote><h2>Leave room for the wine list</h2><p>There is no need to turn dinner into a choice between your wine and theirs. You might order a glass of sparkling wine to start, share your bottle with the main course and finish with a glass of something sweet. If the restaurant requires a purchase from its list, agree that in advance too.</p><p>Our directory links to published policies and distinguishes ordinary dining from private events or membership offers. It is a starting point, not a substitute for asking. Once the arrangement is clear, stop doing the maths and enjoy dinner.</p>'''},
{'slug':'sunday-table','category':'Making plans','title':'Make a little more of Sunday.','deck':'A late lunch, an early dinner and a bottle worth sharing. How to plan around a corkage offer without letting the offer plan your meal.','art':'table','read':'3 minute read','body':'''<p class="lead">Sunday is a useful day for a bottle that needs time. Nobody should be watching the clock through the last glass, and a quieter dinner can be a better occasion than a grand one.</p><p>Some London restaurants publish free-corkage offers for particular Sunday services. The important word is “particular”. A Sunday-evening offer does not mean Sunday lunch, and a regular promotion may exclude special dates.</p><h2>Three places to start</h2><p><a href="../index.html?restaurant=kitchen-w8">Kitchen W8</a> publishes free Sunday-evening corkage with bottle caps and special-date exclusions. <a href="../index.html?restaurant=trinity">Trinity</a> waives corkage fees on Sunday evenings downstairs, with conditions on quantity and wines already on its list. <a href="../index.html?restaurant=maison-francois">Maison François</a> publishes a Sunday-dinner offer from 16:00.</p><p>Those are website-sourced offers, not promises about your reservation. Open the full listing, follow the restaurant’s source and ask whether the offer applies to your date, party size and bottle. The directory records when each source was checked.</p><h2>Buy the wine before Sunday</h2><p>A restaurant may be open when your preferred merchant is not. Check the shop’s hours, allow time to chill white wine and avoid making an ambitious cross-London collection part of a relaxed afternoon. If you have a specific bottle in mind, confirm that the branch has it rather than relying on the retailer’s online catalogue.</p><h2>Give one bottle enough attention</h2><p>For two people, a single interesting bottle can be plenty to build a meal around. Look at the menu before deciding what to bring. A savoury Pinot Noir is often a gentler companion to poultry than a heavily extracted red; a textured white can be more useful across fish and vegetable dishes than the bottle you instinctively save for seafood.</p><p>Free corkage is a welcome extra. The better reason to book is a room you like, food you want to eat and enough time to enjoy both.</p>'''},
{'slug':'pair-the-sauce','category':'At the table','title':'Pair the sauce, not just the protein.','deck':'A few useful wine styles for French bistros, British dining rooms and spice-led menus. No rigid rules required.','art':'glass','read':'4 minute read','body':'''<p class="lead">“Red with meat, white with fish” gets you started, then quickly runs out of road. Butter, chilli, smoke, mushrooms and acidity often tell you more about a dish than its main ingredient.</p><h2>French bistro cooking</h2><p>For a buttery fish dish or roast chicken with a creamy sauce, a restrained Chardonnay can make sense. Look for freshness alongside texture. If mushrooms or earthy flavours lead the plate, Pinot Noir is another useful direction. It need not be a trophy Burgundy to work well.</p><p>Braises and richer beef dishes may call for more structure. Mature Cabernet-led Bordeaux is a reasonable starting point, particularly when its tannins have softened. Ask a merchant about the bottle’s readiness to drink, not simply how long it could be kept.</p><h2>Heat and aromatic spice</h2><p>A little sweetness can be helpful with chilli, which makes off-dry Riesling a useful option. It also brings acidity to rich food. Very tannic, high-alcohol reds can feel harder alongside a hot dish; a fresher, lower-tannin red may be a better fit if that is what you enjoy.</p><p>For a varied table, dry sparkling rosé offers another route. Texture and freshness can carry it across several dishes without pretending it is the perfect answer to all of them.</p><h2>Grills and seafood</h2><p>Chargrilled beef gives Northern Rhône Syrah or a Cabernet blend something to work with. Oysters point in a different direction: Muscadet, Chablis or a dry traditional-method sparkling wine. A rich sauce on the fish may move you towards a fuller white.</p><h2>Take the menu to the merchant</h2><p>Show the actual menu, say what you tend to enjoy and give a total budget. Include corkage in that budget. A good recommendation should answer the meal you are planning, not demonstrate the most obscure appellation in the shop.</p><p>These are editorial suggestions, not restaurant recommendations or claims about stock. Menus change. Your taste matters. The most useful pairing is one that helps everyone enjoy what is on the table.</p>'''},
{'slug':'the-corkage-checklist','category':'Before you go','title':'The five-minute corkage checklist.','deck':'Bottle sizes, service charges and Sunday shop hours. The small questions that make the evening straightforward.','art':'note','read':'3 minute read','body':'''<p class="lead">Most corkage misunderstandings can be avoided with one short conversation before dinner. Here is what to cover.</p><h2>1. Is this the right policy?</h2><p>A private-hire brochure is not a promise to a table of two. A members’ lunch benefit is not a public offer. Make sure the policy applies to the room, service and booking you actually want. Our directory separates these cases rather than treating every mention of corkage as the same thing.</p><h2>2. What are you bringing?</h2><p>Give the wine’s name, vintage, size and quantity. Ask whether bottles already on the list are excluded. Tell the restaurant if you are considering Champagne, a magnum or an older bottle that may need careful opening. Do not assume all formats carry the same fee.</p><h2>3. What will it cost?</h2><p>Confirm the rate and whether service is added. Ask about any minimum purchase from the wine list. A promotional rate may depend on the day or time, and some restaurants price particularly valuable wines differently. Get clarity before the booking, not when the cork is pulled.</p><h2>4. How will the bottle get there?</h2><p>Check the merchant’s actual branch address, opening hours and stock. A shop across London is a place to buy in advance, not a handy stop five minutes before dinner. Transport the wine carefully and ask the restaurant how it would prefer to handle chilling or decanting.</p><h2>5. What if the plan changes?</h2><p>Let the restaurant know if your party size or bottle count changes. If an old bottle is faulty, do not assume you can replace it with another without discussing the arrangement. Their team can help, but it is better not to arrive with an unannounced case.</p><p>Once those questions are settled, there is very little left to organise. Turn up on time, order well and enjoy the bottle you chose.</p>'''}]

def art(kind):
    # Original vector artwork, not a photograph or a depicted restaurant.
    return f'<div class="editorial-art art-{kind}" aria-hidden="true"><svg viewBox="0 0 420 250" fill="none"><ellipse cx="219" cy="212" rx="152" ry="22" fill="currentColor" opacity=".08"/><path d="M119 40h26v46l15 30v90h-56v-90l15-30z" stroke="currentColor" stroke-width="2"/><path d="M119 40h26v22h-26z" fill="currentColor"/><path d="M104 137h56v43h-56z" fill="currentColor" opacity=".17"/><path d="M216 210v-60m-24 60h48m-57-137h66l-6 48c-4 39-49 39-54 0z" stroke="currentColor" stroke-width="2"/><path d="M188 110h56l-2 12c-5 36-47 36-51 0z" fill="currentColor" opacity=".55"/><ellipse cx="310" cy="186" rx="44" ry="23" stroke="currentColor" stroke-width="2"/><ellipse cx="310" cy="186" rx="30" ry="14" stroke="currentColor" opacity=".4"/><path d="M278 77c32-39 62-23 48 4-10 20-41 17-32-7" stroke="currentColor" stroke-width="1.5"/><path d="M299 93l-7 35" stroke="currentColor"/></svg></div>'

def post_card(p):
    return f'<a class="journal-card" href="journal/{p["slug"]}.html">{art(p["art"])}<div class="journal-card-copy"><span class="eyebrow">{p["category"]}</span><h3>{p["title"]}</h3><p>{p["deck"]}</p><span class="read-link">Read the story <span aria-hidden="true">↗</span></span></div></a>'

cards=[]
for r in DATA:
    special=r['scope']!='public'
    cards.append(f'''<article class="restaurant-card" data-id="{r['id']}" data-scope="{r['scope']}" { 'hidden' if special else ''}><div class="card-top"><span class="eyebrow">{esc(r['neighbourhood'])}</span><span class="card-mark" aria-hidden="true">↗</span></div><h3><button type="button" class="card-open" disabled data-restaurant="{r['id']}" aria-haspopup="dialog">{esc(r['name'])}</button></h3><p class="cuisine">{esc(r['cuisine'])}</p><div class="card-bottom"><span class="fee">{esc(r['fee'])}</span><span class="status {'special' if special else ''}">{esc(LABELS[r['scope']])}</span></div></article>''')
body=f'''<main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow">The independent London corkage guide</p><h1>Find a table.<br>Bring <em>your bottle.</em></h1><p class="hero-intro">From neighbourhood favourites to special-occasion dining. Good restaurants, clear corkage policies, and a reason to open something you love.</p><a class="button" href="#directory">Find your next table <span aria-hidden="true">↓</span></a><p class="hero-note">35 public-dining leads · 7 special arrangements</p></div><div class="hero-visual">{art('hero')}<div class="seal">LONDON<br><span>Good food.<br>Your wine.</span><br>CORKAGE CLUB</div><span class="visual-caption">For the bottle you’ve been saving.</span></div></section><section class="directory wrap" id="directory" aria-labelledby="directory-heading"><div class="section-heading"><div><p class="eyebrow">The little black book</p><h2 id="directory-heading">A table for every bottle.</h2></div><p>Website-sourced policies, not personal confirmations.<br>Always agree corkage when you book.</p></div><form id="filters" class="filters" role="search"><div class="search-control"><label for="search">Search the guide</label><input type="search" id="search" placeholder="Restaurant, neighbourhood or cuisine…" autocomplete="off"></div><div><label for="area">Area</label><select id="area"><option value="all">All London</option>{''.join(f'<option>{a}</option>' for a in ['Central','West','East','South','City'])}</select></div><div><label for="scope">Arrangement</label><select id="scope"><option value="public">Public dining</option><option value="all">All 42 listings</option><option value="events">Private / group events</option><option value="members">Members only</option><option value="discretion">Ask management first</option><option value="clarify">Needs clarification</option></select></div><div><label for="sort">Sort</label><select id="sort"><option value="name">Name A–Z</option><option value="area">Area</option></select></div><div class="filter-tail"><label class="check"><input type="checkbox" id="free"> With a public free-corkage offer</label><button type="reset" class="text-button">Reset filters</button></div></form><div class="results-bar"><p id="result-count" role="status" aria-live="polite">35 restaurants · public dining</p><p class="small-note">Sources checked 13 September 2026</p></div><p class="scope-note" id="scope-note">Public dining includes day-specific offers and conditions. See each policy before booking.</p><div class="restaurant-grid" id="restaurant-grid">{''.join(cards)}</div><div id="empty" class="empty" hidden><h3>No tables in this search.</h3><p>Try another neighbourhood or include all arrangements.</p><button class="button" id="clear-search">Clear filters</button></div><noscript><p>Enable JavaScript for filters and detailed policy panels. Read our <a href="policies.html">complete policy list</a> without JavaScript.</p></noscript><div class="directory-foot"><p>Know a good spot we’ve missed?</p><a class="text-link" href="{SUGGEST}" target="_blank" rel="noopener noreferrer">Suggest a restaurant ↗</a></div></section><section class="journal-section wrap"><div class="section-heading"><div><p class="eyebrow">The journal</p><h2>A few notes for the table.</h2></div><a class="text-link" href="journal.html">All stories ↗</a></div><div class="journal-grid">{''.join(post_card(p) for p in POSTS[:3])}</div></section><section class="club-banner wrap"><p class="eyebrow">The Corkage Club</p><h2>Better bottles.<br>Even better company.</h2><p>We’re building a club around good food and shared bottles.<br>Leave your details to hear when membership opens.</p><a class="button" href="club.html#join">Join the waitlist ↗</a></section></main><dialog id="restaurant-dialog" aria-labelledby="detail-title"><button type="button" class="close-dialog" aria-label="Close restaurant details">×</button><div id="detail-content"></div></dialog><script src="script.js" defer></script>'''
(OUT/'index.html').write_text(shell('Find London restaurants with corkage','Explore London restaurants with published corkage policies, clear fees and restrictions, plus notes on what to drink.',body))
(OUT/'journal.html').write_text(shell('The journal','Practical notes on corkage, wine pairing and planning a good London dinner.',f'<main id="main" class="wrap"><header class="page-heading"><p class="eyebrow">From the Corkage Club</p><h1>The journal.</h1><p>What to bring, where to begin, and how to make a little more of dinner.</p><span class="small-note">An undated collection of practical guides. Restaurant policies are dated in the directory.</span></header><div class="journal-grid journal-all">{"".join(post_card(p) for p in POSTS)}</div></main>','Journal'))
(OUT/'journal').mkdir(exist_ok=True)
for i,p in enumerate(POSTS):
    next_p=POSTS[(i+1)%len(POSTS)]
    content=f'<main id="main"><article class="article"><header><a class="back-link" href="../journal.html">← The journal</a><p class="eyebrow">{p["category"]} · {p["read"]}</p><h1>{p["title"]}</h1><p class="article-deck">{p["deck"]}</p><p class="byline">By London Corkage Club · Editorial guide</p></header>{art(p["art"])}<div class="prose">{p["body"]}<aside class="article-note">Restaurant offers can change. Check the source and agree terms directly before your visit. Our wine-style suggestions are editorial, not restaurant or merchant endorsements.</aside></div><div class="article-next"><span class="eyebrow">Read next</span><h2><a href="{next_p["slug"]}.html">{next_p["title"]} ↗</a></h2><a class="text-link" href="../index.html#directory">Find a restaurant →</a></div></article></main>'
    (OUT/'journal'/f'{p["slug"]}.html').write_text(shell(p['title'],p['deck'],content,'Journal','../'))
club=f'''<main id="main" class="wrap"><header class="page-heading"><p class="eyebrow">The Corkage Club</p><h1>For people who like<br>to <em>share a bottle.</em></h1><p>Good food. Interesting wine. The sort of evening you make time for.</p></header><div class="split-content"><div class="prose"><h2>A guide today.<br>A club in the making.</h2><p>For now, our restaurant guide is open to everyone. You do not need to join anything to use it, and listing a restaurant here does not mean it is a club partner.</p><p>We’re exploring a club built around shared bottles, restaurant discovery and a community of people who enjoy both. Membership, events and any partner benefits are still being developed. We are not selling memberships or promising discounts.</p><p>If that sounds like your sort of thing, join the waitlist. We’ll use the details you submit to contact you about the club.</p></div><section id="join" class="join-panel"><p class="eyebrow">Register your interest</p><h2>A seat at the table.</h2><p>Leave your name and email using our Google form. No payment or membership commitment.</p><a class="button" href="{FORM}" target="_blank" rel="noopener noreferrer">Open the waitlist form ↗</a><p class="small-note">Opens Google Forms in a new tab. Google hosts the form and shows the submission confirmation. We cannot confirm receipt from this page.</p></section></div></main>'''
(OUT/'club.html').write_text(shell('The club','A community in the making for London diners who enjoy sharing good wine.',club,'The club'))
about='''<main id="main" class="wrap"><header class="page-heading"><p class="eyebrow">About the guide</p><h1>A good bottle deserves<br>a <em>good table.</em></h1><p>We make it easier to find London restaurants where you can bring your own wine.</p></header><div class="prose about-prose"><h2>Wine without the ceremony</h2><p>It might be a bottle you have saved for years, or one you picked up on the way home. What matters is finding somewhere good to drink it, with food and company to match.</p><p>London Corkage Club is an independent guide. We favour worthwhile dining experiences, from neighbourhood restaurants to a special evening out. The guide is free to browse.</p><h2 id="how-we-check">How we check policies</h2><p>Our listings are based on restaurant websites, FAQs and official documents. Every entry links to its policy source and gives the date that source was checked. This is not a personal confirmation from the restaurant, and it does not guarantee that a promotion is still running.</p><p>We separate public dining, private or group events, member benefits, discretionary arrangements and conflicting policies. Missing fees stay unknown. A website that says nothing about corkage is not evidence that you can bring wine.</p><p>We have researched 227 candidates, but that is not a count of confirmed corkage restaurants. The current guide contains 42 source-backed policy records, including seven special arrangements. Older unverified directory prices are not carried forward.</p><h2>Before you book</h2><p>Tell the restaurant the wine, vintage, size and number of bottles. Check the total charge, service, day restrictions and whether the wine is already on their list. Our editorial pairing ideas are suggestions only. Merchant links are places to consider, not claims about stock, current hours or partnership.</p><h2>Something changed?</h2><p>Please send a correction or suggest a restaurant using the link below. We would rather show a gap than invent a policy.</p>'''+f'<a class="text-link" href="{SUGGEST}" target="_blank" rel="noopener noreferrer">Suggest a restaurant or policy update ↗</a></div></main>'
(OUT/'about.html').write_text(shell('About the guide','Our approach to restaurant selection, corkage sources and policy accuracy.',about,'About'))
policy_body='<main id="main" class="wrap"><header class="page-heading"><h1>The full policy list.</h1><p>Website sources checked 13 September 2026. Reconfirm before booking.</p></header><div class="prose">'+''.join(f'<section id="{r["id"]}"><h2>{esc(r["name"])}</h2><p>{esc(r["neighbourhood"])} · {esc(LABELS[r["scope"]])}</p><h3>{esc(r["fee"])}</h3><p>{esc(r["policy"])}</p><a href="{esc(r["source"])}" target="_blank" rel="noopener noreferrer">Official source ↗</a></section>' for r in DATA)+'</div></main>'
(OUT/'policies.html').write_text(shell('All corkage policies','Accessible text version of every published restaurant policy in the guide.',policy_body))
for name in ['styles.css','script.js','data.json']:
    shutil.copy2(ROOT/name,OUT/name)
shutil.copytree(ROOT/'images',OUT/'images',dirs_exist_ok=True)
print(f'Built {len(DATA)} restaurant records, {len(POSTS)} journal articles and 5 site pages into dist/.')
